package com.novalang.bukkit.types.event;
import com.novalang.bukkit.Requires; import com.novalang.bukkit.types.value.NovaTypeSupport; import com.novalang.runtime.host.JavaTypes; import org.bukkit.entity.Arrow; import org.bukkit.event.player.PlayerPickupArrowEvent;
@Requires(classes = {"org.bukkit.event.player.PlayerPickupArrowEvent"}) public final class NovaPlayerPickupArrowEvent { private NovaPlayerPickupArrowEvent() { } public static void register(JavaTypes.Builder b){b.extension(PlayerPickupArrowEvent.class,"arrow",f->f.returns(Arrow.class).invoke(a->NovaTypeSupport.argument(a,0,PlayerPickupArrowEvent.class).getArrow()));} }
